Object.assign(window.deepArticles, {
  "sakha-people":farEasternIndigenousArticle({
    title:"Sakha people",infoboxKicker:"Turkic people of the middle Lena and Yakutia",
    lead:"The Sakha people, historically called Yakuts in Russian, are the principal indigenous nation of Yakutia and one of the largest non-Russian peoples of the Russian Far Eastern State. Their territorial institutions, language, pastoral traditions, literature, and control of the middle Lena give the Chita federation a political center outside its Russian and Orthodox southern core.",
    canon:"Sakha historical geography, language, pastoral culture, Russian conquest, Soviet autonomy, collectivization, and purge experience are baseline. Their post-1945 territorial bargain and importance inside federal Yakutia follow established Far Eastern federalism; exact census totals, parties, officeholders, and constitutional formulas remain open.",
    sections:[
      {id:"origins",title:"Origins and movement to the Lena",html:"<p>Sakha ethnogenesis combined Turkic-speaking pastoral migrants associated with the Baikal region and older Tungusic, Yukaghir, and other northern populations. Communities adapted horse and cattle husbandry to the middle Lena while northern groups also depended heavily upon fishing, hunting, and reindeer.</p>"},
      {id:"conquest",title:"Russian conquest and tribute",html:"<p>Russian expansion reached the Lena in the seventeenth century, imposed fur tribute, founded Yakutsk, and violently suppressed resistance. Epidemic disease and colonial coercion devastated communities even as Sakha settlement and language continued to expand into parts of the north.</p>"},
      {id:"religion",title:"Orthodoxy and older belief",html:"<p>Most Sakha entered the Orthodox institutional world during imperial rule, yet seasonal rites, sacred landscapes, shamanic practices, and a sky-oriented religious vocabulary persisted. The Far Eastern monarchy presents Orthodoxy as a federal bond while territorial law leaves space for Sakha observance.</p>"},
      {id:"autonomy",title:"Soviet autonomy and repression",html:"<p>The Yakut Autonomous Soviet Socialist Republic was created in 1922. Native-language education and literary development accompanied collectivization, political purges, settlement by Russians and Ukrainians, and state control of livestock, land, mining, and local leadership.</p>"},
      {id:"collapse",title:"The 1945 survival government",html:"<p>Republican offices, district authorities, schools, radio, river administration, farms, and cultural institutions survive the Soviet collapse. Sakha officials possess territorial legitimacy and operating knowledge that southern Russian or Japanese-backed committees cannot readily replace.</p>"},
      {id:"federal",title:"The Chita federal bargain",html:"<p><a href='yakutia.html'>Yakutia</a> enters the restored state through a charter recognizing local government, language, education, customary affairs, and a claim upon resource revenue. Sakha elites accept the crown and external defense order while resisting conversion into an ordinary Russian province.</p>"},
      {id:"economy",title:"Pastoral life and the resource frontier",html:"<p>Horses, cattle, hay, fishing, hunting, forestry, river work, administration, and later mining coexist. Concessions create employment and infrastructure while threatening grazing land, waterways, village autonomy, and the territorial share of diamonds, gold, coal, and timber.</p>"},
      {id:"1985",title:"Sakha society in 1985",html:"<p>By 1985 Sakha is a normal language of territorial politics, rural life, education, literature, and broadcasting. Russian remains dominant in federal administration and high technology. The resulting bilingual order is unequal but strong enough that Sakha identity structures the federation rather than surviving only as private heritage.</p>"}
    ],
    related:[{href:"sakha-language.html",kicker:"Language",label:"Sakha Language"},{href:"yakutia.html",kicker:"Federal homeland",label:"Yakutia"},{href:"yakutsk.html",kicker:"Territorial capital",label:"Yakutsk"},{href:"olonkho.html",kicker:"Epic tradition",label:"Olonkho"},{href:"platon-oyunsky.html",kicker:"Writer and statesman",label:"Platon Oyunsky"},{href:"indigenous-policy-russian-far-eastern-state.html",kicker:"Federal policy",label:"Indigenous Policy"}],
    facts:[["Self-designation","Sakha"],["Historical Russian name","Yakuts"],["Language","Sakha, with extensive Russian bilingualism"],["Primary homeland","Yakutia and the middle Lena basin"],["Language family","Turkic"],["Traditional livelihoods","Horse and cattle pastoralism, fishing, hunting, and northern reindeer work"],["Territorial autonomy since","1922; reconstituted under the Chita federation"],["1985 political position","Principal indigenous nation of the largest federal land"]],
    sources:[{href:"https://en.wikipedia.org/wiki/Yakuts",label:"Historical and ethnographic reference — Sakha people"}]
  }),

  "sakha-language":farEasternIndigenousArticle({
    title:"Sakha language",category:"Languages",infoboxKicker:"Territorial language of Yakutia",
    lead:"Sakha, also known historically as Yakut, is a Siberian Turkic language and the principal indigenous public language of Yakutia. It shares territorial administration, schools, publishing, radio, and cultural life with Russian while remaining structurally distinct from both Russian and the Tungusic languages surrounding it.",
    canon:"The language's Turkic classification, Cyrillic literary standard, Soviet-era development, Russian contact, and use by the Sakha are historical. Its strong territorial role and unequal bilingual relationship inside the Far Eastern federation are extrapolated from the fixed autonomy; exact speaker counts, school rules, and legal clauses remain open.",
    sections:[
      {id:"classification",title:"Classification",html:"<p>Sakha belongs to the northeastern or Siberian branch of the Turkic languages. It is agglutinative, uses vowel harmony, ordinarily places the verb late in the clause, and preserves features that distinguish it sharply from better-known western Turkic languages.</p>"},
      {id:"contact",title:"Contact and northern adaptation",html:"<p>The language contains important Mongolic, Tungusic, and later Russian layers. Its vocabulary and oral traditions reflect pastoral life, rivers, cold, hunting, kinship, landscape, and the long interaction of migrants with older northern peoples.</p>"},
      {id:"writing",title:"Writing and standardization",html:"<p>Missionary and scholarly transcription preceded modern standardization. Soviet language planning experimented with scripts before establishing a Cyrillic alphabet adapted to Sakha sounds. Schools, newspapers, publishing, theater, and administration created a durable literate public.</p>"},
      {id:"oyunsky",title:"Literature and Platon Oyunsky",html:"<p><a href='platon-oyunsky.html'>Platon Oyunsky</a> helped make Sakha a modern political and literary language through poetry, drama, translation, scholarship, and the written preservation of <a href='olonkho.html'>Olonkho</a>. His purge made language memory inseparable from political repression.</p>"},
      {id:"collapse",title:"Continuity through state collapse",html:"<p>Territorial schools, teachers, typesetters, radio workers, archives, and district offices preserve the standard after 1945. Because no outside government can administer Yakutia alone, the language retains practical value rather than depending only upon cultural toleration.</p>"},
      {id:"law",title:"Territorial public status",html:"<p>Sakha is used in Yakutian territorial institutions, local courts and notices where capacity exists, primary education, cultural administration, and broadcasting. Russian controls federal communication, interterritorial business, military service, and most advanced technical documentation.</p>"},
      {id:"urban",title:"Yakutsk and the bilingual city",html:"<p>Urban administration and higher technical life in Yakutsk favor Russian, while Sakha remains visible in education, theater, literature, radio, markets, family life, and territorial politics. Language choice signals profession, district, generation, and political claim.</p>"},
      {id:"status",title:"Status in 1985",html:"<p>Sakha is regionally vigorous but exposed to domain loss in mining towns, federal offices, and advanced education. The archive does not assign it an international endangerment category or precise speaker total; its position is stronger than those of the smaller northern languages.</p>"}
    ],
    related:[{href:"sakha-people.html",kicker:"Speakers",label:"Sakha People"},{href:"yakutia.html",kicker:"Territorial home",label:"Yakutia"},{href:"yakutsk.html",kicker:"Urban center",label:"Yakutsk"},{href:"olonkho.html",kicker:"Oral literature",label:"Olonkho"},{href:"indigenous-policy-russian-far-eastern-state.html",kicker:"Legal context",label:"Indigenous Policy"}],
    facts:[["Alternate names","Sakha, Yakut, Yakutian"],["Family","Siberian Turkic"],["Type","Agglutinative with vowel harmony"],["Writing system","Modified Cyrillic"],["Primary territory","Yakutia"],["Principal contact language","Russian"],["Public domains","Territorial government, education, publishing, radio, theater, and family life"],["1985 status","Regionally strong; precise classification open"]],
    sources:[{href:"https://en.wikipedia.org/wiki/Yakut_language",label:"Linguistic reference — Sakha language"}]
  }),

  "olonkho":farEasternIndigenousArticle({
    title:"Olonkho",category:"Oral literature",infoboxKicker:"Sakha heroic-epic tradition",
    lead:"Olonkho is the Sakha tradition of long heroic epics performed by specialist narrators. Its layered worlds, founders, warriors, families, monsters, ordeals, songs, and spoken performance form the best-known literary emblem of Yakutia and a central institution of Sakha-language cultural life in the Far Eastern State.",
    canon:"Olonkho's oral epic form, specialist performance, mythic scope, and Platon Oyunsky's literary role are historical. Its postwar use in schools, radio, theater, festivals, and federal ceremony is a setting extrapolation; program names, performers, and official commemorative dates remain open.",
    sections:[
      {id:"form",title:"A performed heroic epic",html:"<p>An Olonkho is performed through narrative, characterization, recitative, and song rather than read as an ordinary fixed poem. Skilled performers sustain large casts, repeated formulas, changes of voice, and long sequences from memory and improvisational command.</p>"},
      {id:"world",title:"The three-world cosmos",html:"<p>Stories commonly move among upper, middle, and lower worlds and follow heroic ancestors defending people, households, or the created order. Sacred trees, journeys, contests, marriage, kinship, monsters, and restoration connect cosmic struggle to recognizable social life.</p>"},
      {id:"performers",title:"Olonkhosut",html:"<p>The specialist narrator, or olonkhosut, is valued for memory, voice, stamina, musical distinction, characterization, and knowledge of inherited formulas. A performance tradition survives through apprentices, families, local audiences, recordings, and later schools.</p>"},
      {id:"writing",title:"Collection and literary preservation",html:"<p>Scholars and writers recorded variants as print culture expanded. Written editions preserve endangered repertoires while changing a flexible social performance into a text that can be standardized, taught, excerpted, and claimed by institutions.</p>"},
      {id:"oyunsky",title:"Oyunsky and Nyurgun Bootur",html:"<p><a href='platon-oyunsky.html'>Platon Oyunsky</a> assembled and wrote a major version of Nyurgun Bootur the Swift. His work links the oral tradition to modern Sakha literature and makes later commemoration of the epic inseparable from remembrance of a purge victim.</p>"},
      {id:"collapse",title:"Preservation after 1945",html:"<p>Soviet collapse interrupts publishing and cultural budgets but strengthens local control of archives, radio, schools, and theater. Performers and teachers become custodians of a tradition that territorial institutions use to justify the continuity of Yakutia itself.</p>"},
      {id:"public",title:"Public culture under the monarchy",html:"<p>Territorial festivals, broadcasts, school editions, theater, recordings, and visiting performances bring Olonkho into federal public culture. Chita officials praise it as evidence that the monarchy governs several historic peoples, while Sakha institutions resist reducing it to court folklore.</p>"},
      {id:"meaning",title:"Political meaning",html:"<p>Olonkho supplies a language of endurance, rightful order, defended households, ancestral land, and return after catastrophe. Different audiences can read those themes as Sakha autonomy, federal loyalty, survival after Stalinism, or a broader northern civilizational inheritance.</p>"}
    ],
    related:[{href:"sakha-people.html",kicker:"Cultural community",label:"Sakha People"},{href:"sakha-language.html",kicker:"Language",label:"Sakha Language"},{href:"platon-oyunsky.html",kicker:"Literary preserver",label:"Platon Oyunsky"},{href:"yakutsk.html",kicker:"Institutional center",label:"Yakutsk"},{href:"indigenous-policy-russian-far-eastern-state.html",kicker:"Federal cultural policy",label:"Indigenous Policy"}],
    facts:[["Tradition","Sakha heroic epic"],["Primary medium","Oral performance"],["Specialist performer","Olonkhosut"],["Language","Sakha"],["Common structure","Upper, middle, and lower worlds"],["Major literary figure","Platon Oyunsky"],["Major written cycle","Nyurgun Bootur the Swift"],["1985 public forms","Performance, radio, theater, schools, recordings, and festivals"]],
    sources:[{href:"https://en.wikipedia.org/wiki/Olonkho",label:"Cultural reference — Olonkho"}]
  }),

  "platon-oyunsky":farEasternIndigenousArticle({
    title:"Platon Oyunsky",category:"People",infoboxKicker:"Sakha writer, scholar, and founding republican statesman",
    lead:"Platon Alexeyevich Oyunsky was a Sakha poet, playwright, scholar, translator, and early Soviet statesman who helped establish the Yakut autonomous republic and preserve Olonkho in written form. His death in prison during the Great Purge made him a central figure in the postwar recovery of Sakha political and literary memory.",
    canon:"Oyunsky's birth, writing, political offices, Olonkho scholarship, arrest, and 1939 death precede divergence and are historical. His formal rehabilitation, monuments, institutional names, and use by the Chita monarchy differ after 1941 and remain partly reconstructed.",
    sections:[
      {id:"early",title:"Early life and education",html:"<p>Oyunsky was born in 1893 in Yakutia and entered the emerging Sakha educated public. Teaching, revolutionary politics, Russian and Sakha literacy, and the upheavals of empire and civil war shaped his dual career as organizer and writer.</p>"},
      {id:"state",title:"Formation of autonomous Yakutia",html:"<p>He became a leading official in the creation of the Yakut autonomous republic and chaired its Central Executive Committee from 1923 to 1926. The work tied Sakha territorial recognition to the Soviet constitutional system.</p>"},
      {id:"writer",title:"Poet, dramatist, and translator",html:"<p>Oyunsky wrote poetry, drama, prose, criticism, and translations that demonstrated the range of a modern Sakha literary language. His public writing joined revolutionary vocabulary to northern history, myth, ethics, and social change.</p>"},
      {id:"olonkho",title:"Scholar of Olonkho",html:"<p>His work on <a href='olonkho.html'>Olonkho</a>, especially the written cycle Nyurgun Bootur the Swift, preserved and transformed oral epic. Later readers debate the balance between faithful transmission, literary authorship, and Soviet cultural framing.</p>"},
      {id:"purge",title:"Arrest and death",html:"<p>The Great Purge destroyed much of the early Sakha political and cultural leadership. Oyunsky was arrested in 1938 and died in prison at Yakutsk on 31 October 1939, before the setting's point of divergence.</p>"},
      {id:"collapse",title:"Recovery of his record",html:"<p>After Soviet authority collapses, local archives, writers, teachers, relatives, and former officials recover Oyunsky as both a founder and a victim. His usable public identity no longer depends upon approval from Moscow.</p>"},
      {id:"rehabilitation",title:"Rehabilitation in the Far Eastern State",html:"<p>Yakutian institutions clear his public name and restore his works during the republican or early monarchical transition. The exact decree and date remain open, so the archive does not import the historical Soviet rehabilitation of 1955 automatically.</p>"},
      {id:"legacy",title:"Legacy by 1985",html:"<p>Oyunsky symbolizes Sakha literacy, territorial statehood, cultural recovery, and the danger of allowing a security bureaucracy to define loyalty. Schools, literary institutions, theater, archives, and public commemoration use his work, although exact institutional names remain unsettled.</p>"}
    ],
    related:[{href:"sakha-people.html",kicker:"Nation",label:"Sakha People"},{href:"sakha-language.html",kicker:"Literary medium",label:"Sakha Language"},{href:"olonkho.html",kicker:"Epic scholarship",label:"Olonkho"},{href:"yakutia.html",kicker:"State-building context",label:"Yakutia"},{href:"former-gulag-zones.html",kicker:"Repressive system",label:"Former Gulag Zones"}],
    facts:[["Born","30 December 1893 · Yakutia"],["Died","31 October 1939 · Yakutsk prison"],["Occupations","Poet, playwright, scholar, translator, and politician"],["Political office","Chairman of the Yakut ASSR Central Executive Committee, 1923–1926"],["Language","Sakha"],["Principal cultural association","Olonkho and Nyurgun Bootur the Swift"],["Cause of death","Imprisonment during the Great Purge"],["Far Eastern rehabilitation","Established in principle; exact decree open"]],
    sources:[{href:"https://en.wikipedia.org/wiki/Platon_Oyunsky",label:"Biographical reference — Platon Oyunsky"}]
  }),

  "evenks":farEasternIndigenousArticle({
    title:"Evenks",infoboxKicker:"Tungusic people across the Baikal–Amur and northern forest world",
    lead:"The Evenks are a widely dispersed Tungusic people whose communities extend through the forests between Lake Baikal, the Amur, Yakutia, the Yenisei, Manchuria, and Mongolia. In the fractured postwar order they live across several states and concession zones, making hunting grounds, reindeer routes, language, and family contact matters of international as well as local administration.",
    canon:"Evenk geography, Tungusic language, reindeer, hunting, and cross-border distribution are historical. Their division among the Far Eastern State, Manchukuo, Mongolia, and Siberian successors follows the setting map; exact charters, migration agreements, and 1985 population remain open.",
    sections:[
      {id:"distribution",title:"A people across the taiga",html:"<p>Evenk communities occupy a vast discontinuous zone rather than one compact homeland. River basins, hunting territories, reindeer routes, forests, mining districts, and Russian or Chinese settlements shape local identities and dialects.</p>"},
      {id:"language",title:"Evenki language",html:"<p>Evenki belongs to the northern Tungusic languages and is related to Even and Negidal. Russian, Sakha, Mongolian, and Chinese or Manchurian contact vary by district. The absence of one territorial center makes school and publishing policy difficult.</p>"},
      {id:"livelihood",title:"Hunting, reindeer, and transport",html:"<p>Reindeer may provide transport, milk, hides, and social value while hunting, fishing, gathering, wage work, forestry, and later industrial employment support households. Local economies differ sharply between mobile forest groups and settled districts.</p>"},
      {id:"soviet",title:"Soviet administration",html:"<p>Collectivization, boarding schools, fixed settlements, state hunting enterprises, district councils, literacy campaigns, and repression brought services and administrative recognition alongside forced social transformation.</p>"},
      {id:"partition",title:"Partition after Soviet collapse",html:"<p>Communities west of Lake Baikal fall among Siberian successor states; eastern groups enter the Far Eastern monarchy; related populations remain in Manchukuo, Inner Asia, and Mongolia. Borders divide kin and routes that once existed inside larger empires.</p>"},
      {id:"concessions",title:"The concession frontier",html:"<p>Mining, forestry, roads, survey camps, and airfields create jobs and medical access while displacing hunting grounds. Territorial recognition depends upon maps and registers that mobile families may regard as alien or dangerous.</p>"},
      {id:"federal",title:"Place in Far Eastern federal law",html:"<p>Evenk districts receive local councils, language and school provisions, subsistence protections, and representation through Yakutian or Amur territorial institutions. Small numbers and dispersed residence limit their ability to enforce rights against companies or security offices.</p>"},
      {id:"1985",title:"Evenk life in 1985",html:"<p>Most communities combine settled public services with seasonal movement, wage work, or hunting. Evenki survives unevenly; Russian and Sakha bilingualism expands. Cross-border festivals, family visits, and ethnographic institutions operate under close Japanese and successor-state scrutiny.</p>"}
    ],
    related:[{href:"yakutia.html",kicker:"Principal federal territory",label:"Yakutia"},{href:"manchukuo.html",kicker:"Eastern neighboring state",label:"Manchukuo"},{href:"tannu-tuva.html",kicker:"Inner Asian context",label:"Tannu Tuva"},{href:"evens.html",kicker:"Related Tungusic people",label:"Evens"},{href:"indigenous-policy-russian-far-eastern-state.html",kicker:"Legal framework",label:"Indigenous Policy"}],
    facts:[["Language family","Tungusic"],["Primary geographic band","Taiga from the Yenisei and Baikal toward the Amur and Yakutia"],["Traditional activities","Reindeer transport and herding, hunting, fishing, and gathering"],["Major contact languages","Russian, Sakha, Mongolian, and Chinese or Manchurian languages"],["Postwar states","Far Eastern State, Siberian successors, Manchukuo, and Mongolia"],["Federal status","Dispersed recognized communities and districts"],["Principal political issue","Land, mobility, schools, and concession intrusion"],["1985 language condition","Uneven and locally vulnerable; exact count open"]],
    sources:[{href:"https://en.wikipedia.org/wiki/Evenks",label:"Ethnographic reference — Evenks"}]
  }),

  "evens":farEasternIndigenousArticle({
    title:"Evens",infoboxKicker:"Tungusic people of the Okhotsk, Kolyma, and Yakutian north",
    lead:"The Evens are a Tungusic people dispersed through the Sea of Okhotsk coast, Kolyma, northern Yakutia, Kamchatka, and neighboring districts. Their reindeer, hunting, fishing, coastal travel, and multilingual communities connect the Far Eastern State's inland and maritime north.",
    canon:"Even ethnolinguistic identity, Tungusic language, reindeer and hunting economy, and northeastern distribution are historical. Postwar federal treatment, concession relations, schooling, and language trajectory are setting reconstruction constrained by established northern federalism.",
    sections:[
      {id:"homeland",title:"Okhotsk and inland homelands",html:"<p>Even communities occupy river valleys, taiga, mountain passages, tundra, and coastal districts from the Lena–Kolyma north to the Okhotsk shore and Kamchatka. Distance encourages strong local variation in livelihood and speech.</p>"},
      {id:"language",title:"Even language",html:"<p>Even belongs to the northern Tungusic group and is related to Evenki. Russian and Sakha become major contact languages, while Koryak, Yukaghir, and other local contacts shape particular districts.</p>"},
      {id:"economy",title:"Reindeer, hunting, and the coast",html:"<p>Reindeer support movement and inland subsistence; hunting, fishing, gathering, and coastal exchange add food and trade. Soviet and postwar wage work brings households into herding enterprises, mines, weather stations, ports, schools, and air services.</p>"},
      {id:"collective",title:"Collectivization and settlement",html:"<p>Soviet policy reorganized mobile households into collectives and fixed settlements, created schools and clinics, and placed local production under distant plans. The loss of leaders and religious specialists during repression weakened cultural transmission.</p>"},
      {id:"collapse",title:"Supply crisis after 1945",html:"<p>When union supply breaks, remote settlements lose fuel, flour, ammunition, medicine, veterinary support, and transport. Herds and local knowledge sustain communities, but mine and port authorities often control access to imported necessities.</p>"},
      {id:"federal",title:"Federal districts and representation",html:"<p>Evens are represented through Yakutian, Kolyma, Kamchatkan, and smaller district institutions rather than one national territory. This preserves local administration while dispersing political leverage among several governments.</p>"},
      {id:"industry",title:"Industry and land pressure",html:"<p>Roads, mines, fisheries, and concession surveys offer wages and transport while disturbing migration routes and rivers. Compensation is difficult where land use is seasonal, collective, and poorly represented by permanent cadastral boundaries.</p>"},
      {id:"1985",title:"Evens in 1985",html:"<p>Even identity remains visible in herding, kinship, local schools, crafts, festivals, and mixed-language settlements. Language transmission varies widely, and the archive does not assign one uniform endangerment category to communities spread across several territories.</p>"}
    ],
    related:[{href:"evenks.html",kicker:"Related people",label:"Evenks"},{href:"kolyma.html",kicker:"Northeastern territory",label:"Kolyma"},{href:"yakutia.html",kicker:"Western territory",label:"Yakutia"},{href:"kamchatka.html",kicker:"Pacific territory",label:"Kamchatka"},{href:"indigenous-policy-russian-far-eastern-state.html",kicker:"Federal policy",label:"Indigenous Policy"}],
    facts:[["Language","Even"],["Language family","Tungusic"],["Principal regions","Okhotsk coast, Kolyma, northern Yakutia, and Kamchatka"],["Traditional activities","Reindeer herding, hunting, fishing, and gathering"],["Main contact languages","Russian and Sakha"],["Federal organization","Several territorial and district institutions"],["Principal modern pressure","Settlement, industrial land use, and language shift"],["1985 classification","Varies by district; exact status open"]],
    sources:[{href:"https://en.wikipedia.org/wiki/Evens",label:"Ethnographic reference — Evens"}]
  }),

  "yukaghir-people":farEasternIndigenousArticle({
    title:"Yukaghir people",infoboxKicker:"Small indigenous communities of the Kolyma and tundra north",
    lead:"The Yukaghirs are a small indigenous people of the Kolyma, Indigirka, and northeastern tundra whose surviving communities speak Tundra Yukaghir or Kolyma Yukaghir alongside Russian, Sakha, Even, or Chukchi. Their extreme demographic and linguistic vulnerability makes them a test of whether Far Eastern territorial autonomy protects communities too small to control a province.",
    canon:"Yukaghir geography, two surviving languages, small population, and historic interaction with Sakha, Even, and Chukchi communities are baseline. Their federal recognition, schools, land rights, and 1985 language condition are extrapolated; precise population and legal categories remain open.",
    sections:[
      {id:"past",title:"A reduced northern people",html:"<p>Yukaghir-speaking groups once occupied a wider northeastern range. Epidemics, warfare, tribute, assimilation, migration, Russian colonization, and absorption into neighboring peoples reduced both territory and population over centuries.</p>"},
      {id:"languages",title:"Tundra and Kolyma Yukaghir",html:"<p>The surviving languages form a small family whose wider relationships remain disputed. Tundra and Kolyma Yukaghir are distinct enough that preservation requires separate teachers, texts, recordings, and community work.</p>"},
      {id:"livelihood",title:"River, tundra, and forest life",html:"<p>Hunting, fishing, reindeer, dog transport, gathering, and exchange with neighboring peoples support communities adapted to river and tundra cycles. Soviet settlement and wage work add schools, stores, clinics, herding enterprises, and administrative posts.</p>"},
      {id:"soviet",title:"Soviet recognition and assimilation",html:"<p>Ethnographic classification and local schooling made Yukaghirs legible to the state while collectivization, boarding education, and settlement weakened intergenerational language use. Small communities could disappear statistically inside larger district categories.</p>"},
      {id:"collapse",title:"Post-collapse isolation",html:"<p>The failure of supply and district administration threatens villages that depend upon medicine, fuel, transport, and communications. Local subsistence knowledge prevents complete abandonment, yet population dispersal and movement toward larger towns accelerate.</p>"},
      {id:"federal",title:"Recognition inside Yakutia and Kolyma",html:"<p>Yukaghir communities receive district representation, cultural and school provisions, and subsistence claims through <a href='yakutia.html'>Yakutia</a> and <a href='kolyma.html'>Kolyma</a>. No separate sovereign or large territorial land is created.</p>"},
      {id:"language",title:"Preservation policy",html:"<p>Local classes, primers, radio recordings, oral-history work, teacher training, and support for seasonal land use preserve a limited public presence. Russian, Sakha, Even, and Chukchi remain necessary for most wider communication.</p>"},
      {id:"1985",title:"Status in 1985",html:"<p>Both Yukaghir languages are endangered in practical terms by small speaker communities and bilingual shift. Exact census totals and formal international classifications are unavailable; territorial policy slows decline but does not reverse the demographic scale of the problem.</p>"}
    ],
    related:[{href:"yakutia.html",kicker:"Western territorial home",label:"Yakutia"},{href:"kolyma.html",kicker:"Eastern territorial home",label:"Kolyma"},{href:"evens.html",kicker:"Neighboring people",label:"Evens"},{href:"chukchi-people.html",kicker:"Northeastern neighbor",label:"Chukchi People"},{href:"indigenous-policy-russian-far-eastern-state.html",kicker:"Protective policy",label:"Indigenous Policy"}],
    facts:[["Surviving languages","Tundra Yukaghir and Kolyma Yukaghir"],["Language family","Independent small family; wider relationships disputed"],["Principal regions","Kolyma, Indigirka, and northeastern tundra"],["Neighboring peoples","Sakha, Evens, Chukchi, and Russians"],["Traditional activities","Hunting, fishing, reindeer, and gathering"],["Federal status","Small recognized communities within Yakutia and Kolyma"],["Principal risk","Demographic dispersal and language shift"],["1985 language condition","Endangered; exact classifications open"]],
    sources:[{href:"https://en.wikipedia.org/wiki/Yukaghir_people",label:"Ethnographic and linguistic reference — Yukaghir people"}]
  }),

  "koryaks":farEasternIndigenousArticle({
    title:"Koryaks",infoboxKicker:"Reindeer and coastal people of northern Kamchatka",
    lead:"The Koryaks are an indigenous people of northern Kamchatka and adjoining Okhotsk and Bering districts. Inland reindeer-herding and coastal fishing communities share related languages and political institutions while facing different relationships with settlement, fisheries, mining, and Japanese-supervised maritime security.",
    canon:"Koryak geography, inland and coastal economic distinction, Chukotko-Kamchatkan language, and Soviet autonomous district are historical. Their place within federal Kamchatka and the protected Far Eastern State is extrapolated; exact charter, census, district boundaries, and language status remain open.",
    sections:[
      {id:"homeland",title:"Northern Kamchatkan homeland",html:"<p>Koryak communities occupy a large northern peninsula and mainland zone between the Sea of Okhotsk and Bering approaches. Mountain, tundra, river, and coast produce local societies connected by travel and kinship but separated by difficult terrain.</p>"},
      {id:"groups",title:"Reindeer and coastal communities",html:"<p>Inland groups center reindeer herding and seasonal movement; coastal groups emphasize fishing, marine hunting, dogs, boats, and settled shore life. These are broad economic patterns rather than two sealed peoples.</p>"},
      {id:"language",title:"Koryak and related speech",html:"<p>Koryak belongs to the Chukotko-Kamchatkan family and is closely related to Chukchi and Alutor. Russian becomes the principal wider language, while local multilingualism links Koryaks to Evens, Itelmens, and neighboring settlements.</p>"},
      {id:"conquest",title:"Russian conquest and tribute",html:"<p>Seventeenth- and eighteenth-century Russian expansion imposed tribute, forts, trade, mission activity, and repeated violence. Disease and colonial disruption reduced populations and altered relations among Koryaks, Itelmens, Chukchi, and Russians.</p>"},
      {id:"soviet",title:"Autonomous district and collectivization",html:"<p>The Soviet state created a Koryak autonomous district and reorganized herding, fishing, schools, settlement, and local administration. Recognition supplied institutions while boarding education and planned production strengthened Russian-language dependence.</p>"},
      {id:"federal",title:"Place inside Kamchatka",html:"<p>After 1945 Koryak district institutions become part of the <a href='kamchatka.html'>Kamchatkan federal territory</a>. Local councils and land provisions survive beneath the territorial government at Petropavlovsk and the strategic limits imposed by Japan.</p>"},
      {id:"industry",title:"Fisheries, herds, and concessions",html:"<p>Commercial fisheries, processing, mineral surveys, airfields, and roads increase wage employment and state reach. Herd routes and coastal access require legal protection where concession maps divide continuous seasonal landscapes.</p>"},
      {id:"1985",title:"Koryak society in 1985",html:"<p>Russian is widespread in administration and education, while Koryak survives most strongly in families, herding districts, cultural institutions, and local broadcasting. The exact balance differs sharply among coastal towns and inland communities.</p>"}
    ],
    related:[{href:"kamchatka.html",kicker:"Federal territory",label:"Kamchatka"},{href:"petropavlovsk-kamchatsky.html",kicker:"Territorial capital",label:"Petropavlovsk-Kamchatsky"},{href:"itelmens.html",kicker:"Kamchatkan neighbor",label:"Itelmens"},{href:"chukchi-people.html",kicker:"Related northeastern people",label:"Chukchi People"},{href:"indigenous-policy-russian-far-eastern-state.html",kicker:"Federal policy",label:"Indigenous Policy"}],
    facts:[["Language","Koryak, with widespread Russian bilingualism"],["Language family","Chukotko-Kamchatkan"],["Principal region","Northern Kamchatka and adjoining mainland"],["Broad livelihood groups","Inland reindeer herders and coastal fishing or marine communities"],["Historical autonomy","Koryak autonomous district"],["Federal parent territory","Kamchatka"],["Principal modern pressure","Settlement, fisheries, concessions, and language shift"],["1985 institutional status","Recognized districts within federal Kamchatka"]],
    sources:[{href:"https://en.wikipedia.org/wiki/Koryaks",label:"Ethnographic reference — Koryaks"}]
  }),

  "itelmens":farEasternIndigenousArticle({
    title:"Itelmens",infoboxKicker:"Indigenous river and fishing people of Kamchatka",
    lead:"The Itelmens are an indigenous people of the Kamchatka Peninsula whose riverine fishing societies suffered catastrophic population loss, conquest, disease, and assimilation after Russian expansion. By 1985 their language and distinct institutions survive on a much smaller scale than their historical territory, making cultural recovery a central issue of Kamchatkan federal policy.",
    canon:"Itelmen Kamchatkan homeland, fishing culture, Russian conquest, demographic catastrophe, intermarriage, and language decline are historical. Their Far Eastern legal recognition and 1985 preservation institutions are extrapolated; exact speaker counts, schools, and district rights remain open.",
    sections:[
      {id:"homeland",title:"Kamchatka River societies",html:"<p>Itelmen communities were concentrated in the Kamchatka River valley and other parts of the peninsula. Salmon runs, fishing, hunting, gathering, stored foods, boats, winter houses, kin networks, and trade supported dense settled societies by northern standards.</p>"},
      {id:"conquest",title:"Conquest and demographic collapse",html:"<p>Russian campaigns, tribute demands, reprisals, local wars, and epidemic disease devastated the indigenous population during the conquest of Kamchatka. The scale of loss transformed every later cultural and demographic relationship.</p>"},
      {id:"assimilation",title:"Intermarriage and Kamchadal identity",html:"<p>Russian settlers and Itelmen families intermarried, and many descendants entered Russian-speaking Orthodox communities often described as Kamchadal. This mixed society preserved local food, fishing, vocabulary, and family memory even where distinct Itelmen speech declined.</p>"},
      {id:"language",title:"Itelmen language",html:"<p>Itelmen belongs to the Kamchatkan branch commonly associated with the Chukotko-Kamchatkan family, although its relationship to the Chukotkan languages is distant. Russian expansion and settlement greatly reduced intergenerational transmission.</p>"},
      {id:"soviet",title:"Soviet classification and settlement",html:"<p>Soviet ethnography recognized the people and supplied schooling, clinics, and administrative categories while collective fishing, standardized settlements, and Russian-language education continued assimilation. Small numbers made cultural institutions fragile.</p>"},
      {id:"federal",title:"Recognition under Kamchatkan federal law",html:"<p>The Far Eastern State recognizes Itelmen communities through Kamchatkan districts, cultural bodies, subsistence rights, and local school or archive programs. They do not control the territorial government or possess a separate large federal land.</p>"},
      {id:"fisheries",title:"Salmon, rivers, and commercial pressure",html:"<p>Industrial fishing and processing threaten the river systems central to food and identity while offering wage work. Licensing, river access, spawning protection, and community shares therefore carry cultural as well as economic importance.</p>"},
      {id:"1985",title:"Status in 1985",html:"<p>Itelmen is severely endangered in practical terms, with most community members using Russian in wider life. Recording, local teaching, oral history, fishing rights, and family cultural work preserve a distinct people whose historical losses cannot be reversed by ceremonial recognition alone.</p>"}
    ],
    related:[{href:"kamchatka.html",kicker:"Peninsula homeland",label:"Kamchatka"},{href:"petropavlovsk-kamchatsky.html",kicker:"Territorial center",label:"Petropavlovsk-Kamchatsky"},{href:"koryaks.html",kicker:"Northern neighbor",label:"Koryaks"},{href:"sea-of-okhotsk-transport-system.html",kicker:"Maritime economy",label:"Sea of Okhotsk Transport System"},{href:"indigenous-policy-russian-far-eastern-state.html",kicker:"Protective framework",label:"Indigenous Policy"}],
    facts:[["Homeland","Kamchatka Peninsula, especially river valleys"],["Language","Itelmen"],["Language family","Kamchatkan branch associated with Chukotko-Kamchatkan"],["Traditional economic center","Salmon fishing, hunting, gathering, and stored foods"],["Historical rupture","Russian conquest, epidemic disease, and assimilation"],["Common mixed identity","Kamchadal"],["Federal status","Recognized communities within Kamchatka"],["1985 language condition","Severely endangered in practical terms; exact count open"]],
    sources:[{href:"https://en.wikipedia.org/wiki/Itelmens",label:"Ethnographic reference — Itelmens"}]
  }),

  "chukchi-people":farEasternIndigenousArticle({
    title:"Chukchi people",infoboxKicker:"Tundra and maritime people of the Bering northeast",
    lead:"The Chukchi are the principal indigenous people of Chukotka, with inland reindeer-herding and maritime coastal traditions linking the tundra, Bering Strait, Arctic Ocean, and North Pacific. Their long resistance to Russian conquest and territorial concentration give Chukotka a stronger indigenous political identity than most northern districts of the Far Eastern monarchy.",
    canon:"Chukchi homeland, reindeer and maritime economies, resistance to Russian conquest, Soviet collectivization, and Chukotko-Kamchatkan language are historical. Their autonomous status within the Far Eastern State is fixed through Chukotka; exact assemblies, leaders, population, and cross-Bering arrangements remain open.",
    sections:[
      {id:"homeland",title:"Chukotkan homeland",html:"<p>Chukchi communities occupy the peninsula and adjoining tundra between the Chukchi and Bering seas. Inland and coastal routes connect reindeer country, marine hunting grounds, rivers, trading points, and settlements across a region closer to Alaska than to Chita.</p>"},
      {id:"economies",title:"Reindeer and maritime economies",html:"<p>Inland households organize life around reindeer herds, migration, transport, meat, hides, and exchange. Coastal communities emphasize walrus, seal, whale, fish, dogs, boats, and shore settlements. Trade links the two systems.</p>"},
      {id:"resistance",title:"Resistance to Russian expansion",html:"<p>Chukchi communities resisted tribute and military incorporation more successfully and for longer than many Siberian peoples. Russian authority eventually relied upon trade, negotiated relations, mission activity, and limited administration as well as force.</p>"},
      {id:"language",title:"Language and oral tradition",html:"<p><a href='chukchi-language.html'>Chukchi</a> belongs to the Chukotko-Kamchatkan family and is closely related to Koryak. Oral narrative, song, personal naming, ecological vocabulary, and local knowledge carry distinctions that Russian-language administration cannot reproduce fully.</p>"},
      {id:"soviet",title:"Soviet autonomy and collectivization",html:"<p>Soviet rule created autonomous institutions, schools, clinics, state farms, ports, and airfields while collectivizing herds and marine production, settling mobile families, suppressing religion, and expanding Russian-language public life.</p>"},
      {id:"transition",title:"Chukotka after 1945",html:"<p>Local authorities, herding and coastal enterprises, security detachments, and village councils preserve order during collapse. Japanese power closes the Pacific strategic question, while remoteness forces the first Far Eastern republic to recognize broad internal autonomy.</p>"},
      {id:"bering",title:"The Bering frontier",html:"<p>Kinship and cultural connections cross the Bering Strait, but international contact is filtered through Japanese security and the American Arctic aid system. Trade, rescue, weather, radio, and family visits carry diplomatic weight far beyond their volume.</p>"},
      {id:"1985",title:"Chukchi society in 1985",html:"<p>Chukchi institutions influence territorial policy on herds, marine hunting, village supply, schools, and local justice. Russian remains essential for administration and higher education. Autonomy preserves collective political weight while concession and security systems constrain it.</p>"}
    ],
    related:[{href:"chukchi-language.html",kicker:"Language",label:"Chukchi Language"},{href:"chukotka.html",kicker:"Autonomous homeland",label:"Chukotka"},{href:"koryaks.html",kicker:"Related people",label:"Koryaks"},{href:"yukaghir-people.html",kicker:"Western neighbor",label:"Yukaghir People"},{href:"american-arctic-aid.html",kicker:"Cross-Bering contact",label:"American Arctic Aid"},{href:"indigenous-policy-russian-far-eastern-state.html",kicker:"Federal context",label:"Indigenous Policy"}],
    facts:[["Self-designation","Luorawetlat / related local forms"],["Language","Chukchi"],["Language family","Chukotko-Kamchatkan"],["Homeland","Chukotka and the Bering northeast"],["Broad livelihood groups","Inland reindeer herders and maritime coastal communities"],["Historical distinction","Long resistance to Russian tribute and conquest"],["Federal homeland","Chukotka Autonomous Territory"],["1985 political position","Strong territorial indigenous constituency under Japanese-protected federal rule"]],
    sources:[{href:"https://en.wikipedia.org/wiki/Chukchi_people",label:"Ethnographic reference — Chukchi people"}]
  }),

  "chukchi-language":farEasternIndigenousArticle({
    title:"Chukchi language",category:"Languages",infoboxKicker:"Indigenous language of the Bering northeast",
    lead:"Chukchi is a Chukotko-Kamchatkan language spoken across Chukotka by inland and coastal communities. It possesses a Soviet-standardized Cyrillic literary form and a limited public presence in territorial schools, radio, publishing, and cultural institutions, while Russian dominates federal administration and most advanced education.",
    canon:"The language's classification, close relation to Koryak, Cyrillic writing, Soviet standardization, and historic endangerment pressures are baseline. Its use under Chukotkan autonomy and the Far Eastern State is extrapolated; exact speakers, school hours, media output, and formal 1985 classification remain open.",
    sections:[
      {id:"classification",title:"Classification",html:"<p>Chukchi belongs to the Chukotkan branch of the Chukotko-Kamchatkan family. It is closely related to Koryak and more distantly connected to Alutor, Kerek, and Itelmen within the wider regional grouping.</p>"},
      {id:"structure",title:"Structure",html:"<p>The language is polysynthetic and agglutinative, building complex words from multiple meaningful elements. Its sound system, grammar, vocabulary, and discourse reflect a linguistic history independent of Russian and neighboring Tungusic languages.</p>"},
      {id:"dialects",title:"Regional and livelihood variation",html:"<p>Speech varies across the peninsula and between communities with different coastal, tundra, and settlement histories. A literary standard enables common schooling and print but does not erase local pronunciation, vocabulary, or oral forms.</p>"},
      {id:"writing",title:"Writing and literacy",html:"<p>Early Soviet language planning created a Latin-based alphabet before replacing it with a modified Cyrillic system. Primers, teacher training, newspapers, translations, and local administration established literacy in a language previously transmitted chiefly through speech.</p>"},
      {id:"shift",title:"Russian-language shift",html:"<p>Boarding education, military service, administration, mixed settlements, wage work, and higher education increase Russian use. Children may understand Chukchi while preferring Russian, creating a gap between ethnic identification and active command of the language.</p>"},
      {id:"autonomy",title:"Territorial public use",html:"<p>Chukotkan autonomy supports local classes, cultural broadcasting, notices, publishing, interpreter work, and oral-history recording. Russian remains the language of federal law, external trade, most technical systems, and communication with Chita or Japan.</p>"},
      {id:"media",title:"Radio, schools, and recorded speech",html:"<p>Radio is especially useful across dispersed settlements. Recorded stories, songs, ecological knowledge, and family histories preserve voices beyond the classroom, while village teachers and cultural workers determine whether materials remain socially used.</p>"},
      {id:"status",title:"Status in 1985",html:"<p>Chukchi is endangered by bilingual shift despite territorial recognition and continued use in some families and work settings. The archive does not fix a speaker count or import a later international label; vitality differs between remote communities and Russian-dominant towns.</p>"}
    ],
    related:[{href:"chukchi-people.html",kicker:"Speakers",label:"Chukchi People"},{href:"chukotka.html",kicker:"Territorial home",label:"Chukotka"},{href:"koryaks.html",kicker:"Closest major related people",label:"Koryaks"},{href:"yukaghir-people.html",kicker:"Neighboring language world",label:"Yukaghir People"},{href:"indigenous-policy-russian-far-eastern-state.html",kicker:"Legal framework",label:"Indigenous Policy"}],
    facts:[["Family","Chukotko-Kamchatkan"],["Branch","Chukotkan"],["Closest major relative","Koryak"],["Writing system","Modified Cyrillic; earlier Soviet Latin alphabet"],["Primary territory","Chukotka"],["Principal contact language","Russian"],["Public domains","Local education, radio, cultural work, notices, and oral-history archives"],["1985 condition","Endangered by bilingual shift; precise label open"]],
    sources:[{href:"https://en.wikipedia.org/wiki/Chukchi_language",label:"Linguistic reference — Chukchi language"}]
  }),

  "indigenous-policy-russian-far-eastern-state":farEasternIndigenousArticle({
    title:"Indigenous policy of the Russian Far Eastern State",category:"Public policy",infoboxKicker:"Territorial autonomy, language, land, and northern administration",
    lead:"Indigenous policy in the Russian Far Eastern State is the federal and territorial system governing representation, language, schools, customary institutions, subsistence land, reindeer and marine economies, resource concessions, public service, and relations with the Orthodox crown. It combines real territorial recognition with semi-authoritarian administration, Russian cultural dominance, and Japanese-backed economic pressure.",
    canon:"The state's federal form, Orthodox monarchy, Japanese strategic supremacy, northern territorial autonomy, uneven reach, concession economy, and multimodal public-service system are established. Specific statutes, ministries, quotas, school codes, land courts, and officeholders remain working reconstruction.",
    sections:[
      {id:"inheritance",title:"Imperial and Soviet inheritances",html:"<p>Russian tribute, mission, settlement, and administrative traditions coexist with Soviet autonomous districts, local soviets, written languages, schools, collective enterprises, boarding systems, security policing, and ethnographic classification. The Far Eastern State inherits both recognition and coercion.</p>"},
      {id:"federal",title:"Federal territorial recognition",html:"<p>Yakutia and Chukotka possess strong territorial identities, while Koryak, Evenk, Even, Yukaghir, Itelmen, and other communities work through districts, councils, and charter provisions inside larger lands. Representation follows geography and administrative capacity more than one uniform ethnic formula.</p>"},
      {id:"language",title:"Language policy",html:"<p>Territorial languages may be used in local schools, culture, radio, notices, and some administration. Russian remains the federal, military, interterritorial, and principal technical language. Support ranges from a broad Sakha public sphere to documentation and small classes for severely endangered languages.</p>"},
      {id:"land",title:"Land and subsistence",html:"<p>Charters recognize reindeer routes, hunting grounds, fisheries, marine hunting, village waters, and seasonal use. Converting these practices into surveyed property boundaries is difficult and often favors ministries or concession companies with permanent records and lawyers.</p>"},
      {id:"services",title:"Schools, medicine, and transport",html:"<p>Boarding schools remain controversial because they deliver education at the cost of family and language separation. Mobile clinics, village teachers, radio, civil aviation, tracked transport, and seasonal hostels offer alternatives but require sustained subsidy.</p>"},
      {id:"religion",title:"Religion and the Orthodox crown",html:"<p>The monarchy privileges Orthodoxy in ceremony and public identity. Local Christian practice often incorporates older relationships to landscape and ancestors, while shamanic and indigenous rites receive uneven tolerance. Conversion is not a formal condition of citizenship.</p>"},
      {id:"concessions",title:"Resource concessions and company power",html:"<p>Japanese and Manchukuoan-backed mining, fisheries, forestry, and transport create revenue, wages, clinics, roads, and airfields. They also concentrate policing, housing, stores, and evacuation power in employers whose interests conflict with mobile land use and territorial autonomy.</p>"},
      {id:"balance",title:"The 1985 balance",html:"<p>The system prevents complete administrative erasure and gives several peoples durable public institutions. It does not create equality. Russian language, company leverage, security priorities, demographic settlement, and Japanese strategic control limit the autonomy that federal law advertises.</p>"}
    ],
    related:[{href:"northern-integration-russian-far-east.html",kicker:"Federal process",label:"Northern Integration"},{href:"yakutia.html",kicker:"Largest autonomous land",label:"Yakutia"},{href:"chukotka.html",kicker:"Bering autonomy",label:"Chukotka"},{href:"northern-resource-concessions-russian-far-east.html",kicker:"Economic pressure",label:"Northern Resource Concessions"},{href:"far-eastern-civil-aviation.html",kicker:"Public-service network",label:"Far Eastern Civil Aviation"},{href:"russian-far-eastern-state.html",kicker:"State context",label:"Russian Far Eastern State"}],
    facts:[["State form","Federal Orthodox semi-authoritarian monarchy"],["Common federal language","Russian"],["Strongest territorial indigenous language","Sakha"],["Main policy instruments","Charters, districts, schools, radio, land-use rights, and transport subsidies"],["Key subsistence sectors","Reindeer, hunting, fishing, marine hunting, and gathering"],["Principal external constraint","Japanese strategic and concession power"],["Persistent internal constraint","Russian linguistic and administrative dominance"],["1985 assessment","Real recognition joined to unequal implementation"]]
  })
});

const addFarEasternIndigenousRelated = (slug,items) => {
  const article=window.deepArticles[slug];
  if(!article)return;
  article.related=article.related||[];
  for(const item of items)if(!article.related.some(existing=>existing.href===item.href))article.related.unshift(item);
};

